// Test script for the /check endpoint
const app = require('./app');
const request = require('supertest');

describe('POST /check', () => {
  it('should evaluate a simple rule expression', async () => {
    const res = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 },
      });
    expect(res.statusCode).toEqual(200);
    expect(res.body.result).toBe(true);
  });

  it('should evaluate a complex rule expression', async () => {
    const res = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.user.age >= 18 && ctx.user.isActive',
        context: { user: { age: 25, isActive: true } },
      });
    expect(res.statusCode).toEqual(200);
    expect(res.body.result).toBe(true);
  });

  it('should return 400 for invalid expressions', async () => {
    const res = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.invalid.property',
        context: {},
      });
    expect(res.statusCode).toEqual(400);
    expect(res.body.error).toBeDefined();
  });
});

