const request = require('supertest');
const app = require('./app.js');

describe('POST /check', () => {
  it('should evaluate a simple rule expression', async () => {
    const res = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 },
      });
    expect(res.statusCode).toEqual(200);
    expect(res.body.result).toEqual(true);
  });

  it('should handle errors in rule evaluation', async () => {
    const res = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.invalidExpression',
        context: { amount: 150 },
      });
    expect(res.statusCode).toEqual(400);
    expect(res.body.error).toBeDefined();
  });
});

const express = require('express');
const app = express();
app.use(express.json());

// Evaluate a caller-supplied rule expression against the request.
function evalRule(req) {
  const expr = req.body.rule; // e.g. 'ctx.amount > 100'
  const ctx = { ctx: req.body.context, req };
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req); // dynamic eval
}

app.post('/check', (req, res) => {
  try {
    const result = evalRule(req);
    res.json({ result });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Test the endpoint
const http = require('http');

const testPostCheck = () => {
  const data = JSON.stringify({
    rule: 'ctx.amount > 100',
    context: { amount: 150 },
  });

  const options = {
    hostname: 'localhost',
    port: 3000,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length,
    },
  };

  const req = http.request(options, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk;
    });
    res.on('end', () => {
      console.log('Response:', body);
      server.close();
    });
  });

  req.on('error', (err) => {
    console.error('Error:', err.message);
    server.close();
  });

  req.write(data);
  req.end();
};

setTimeout(testPostCheck, 1000);

